        sum by (pod) (
            rate(container_network_receive_packets_dropped_total{interface="eth0", namespace="obs", node="k8s-node2"}[5m])
        ) / 
        sum by (pod) (
            rate(container_network_receive_packets_total{interface="eth0", namespace="obs", node="k8s-node2"}[5m])
        )
    ) * 100
