))
  * on(node) 
  group_left()
kube_pod_info{k8s_app="ts-news-service", status="running"}

topk(1, 
    (
        rate(node_cpu_seconds_total{job="gateway", cpu=~"^[0-9]+$"}[1m])
        /
        sum(rate(node_cpu_seconds_total{job="gateway"}[1m])) by (instance)
    ) * 100
)
* on(instance) group_left()
node_load1{job="gateway", load_average_1m<0.8}

max(
  irate(container_network_receive_errors_total{statefulset="tsdb-mysql", interface="docker0"}[24h])
) by (node)
max(
  sum(container_network_receive_errors_total{statefulset="tsdb-mysql", interface="docker0"}[24h])
) by (node)

sum(node_procs_blocked) by (instance) {
  instance: instance
  AND
  (pod matches "tsdb-mysql-[0-9]+")
}

(node_disk_write_time_seconds_total[4h] / 4h) / 1e6 > 50 AND
(
  # Assuming node_filesystem_size_bytes metric is available
  node_filesystem_avail_bytes{device="/dev/mapper/ubuntu--vg-ubuntu--lv"} / node_filesystem_size_bytes{device="/dev/mapper/ubuntu--vg-ubuntu--lv"}
) * 100

(
  rate(container_network_receive_bytes_total{job="kubelet"}[5m]) 
  > 2 * rate(container_network_transmit_bytes_total[5m])
) AND (
  (sum(rate(container_fs_reads_bytes_total[5m])) + sum(rate(container_fs_writes_bytes_total[5m]))) * 8 / 1024 > 200 # converting B/s to KB/s
) AND (
  sum by (pod)(node_disk_io_time_seconds_total{device="cni0", container!="tempo-query"})[5m] > 1e-8
)

