histogram_quantile(0.9, sum(rate(traces_spanmetrics_latency_bucket[5m])) by (le)) offset 24h
abs(
  (
    histogram_quantile(0.9, sum(rate(traces_spanmetrics_latency_bucket[5m])) by (le))
  ) - 
  (
    histogram_quantile(0.9, sum(rate(traces_spanmetrics_latency_bucket[5m])) by (le)) offset 24h
  )
)

